from artifact_tool import Blob,SpreadsheetFile
import json,html,collections,pathlib
src='/mnt/data/Tablero_ONU_Visual_2026-10-27.xlsx'
w=SpreadsheetFile.import_xlsx(Blob.load(src))
def records(name, columns):
 s=w.worksheets.get_item(name); data=s.get_range('A1:M80').values; return [dict(zip(columns,r[:len(columns)])) for r in data[1:] if r[0] is not None]
mand=records('MANDATOS',['tema','nombre','nameEN','alcance','anio','organo','creacion','renovacion','metodos','revision','nota','indiceES','indiceEN'])
trazas=records('TRAZABILIDAD',['id','tema','anio','clase','organo','simbolo','nota','url','control'])
alertas=records('CONTROL Y FUENTES',['id','simbolo','tema','problema','nivel','accion','url'])
codigos=records('NOMENCLATURA',['simbolo','organo','tipo','explicacion','riesgo','url'])
selection=records('SELECCIÓN',['paso','actor','regla','riesgo','url'])
for r in [*mand,*trazas,*alertas,*codigos,*selection]:
 for k,v in list(r.items()):
  if v is None:r[k]=''
DATA=json.dumps(dict(mandatos=mand,trazas=trazas,alertas=alertas,codigos=codigos,seleccion=selection),ensure_ascii=False).replace('</','<\\/')
